"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[849],{6164:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/docs/intro","label":"Introduction","docId":"intro","unlisted":false},{"type":"category","label":"File Format","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/file-format/glossary","label":"Glossary","docId":"file-format/glossary","unlisted":false},{"type":"link","href":"/docs/file-format/evaluation-criteria","label":"File Format Evaluation Criteria","docId":"file-format/evaluation-criteria","unlisted":false},{"type":"link","href":"/docs/file-format/existing-formats","label":"Examples","docId":"file-format/existing-formats","unlisted":false}],"href":"/docs/file-format/intro"},{"type":"category","label":"Capture Interface","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/capture-interface/glossary","label":"Glossary","docId":"capture-interface/glossary","unlisted":false},{"type":"link","href":"/docs/capture-interface/components","label":"Components","docId":"capture-interface/components","unlisted":false},{"type":"link","href":"/docs/capture-interface/usual_interfaces","label":"Usual Interfaces in Practice","docId":"capture-interface/usual_interfaces","unlisted":false},{"type":"link","href":"/docs/capture-interface/evaluation_criteria","label":"Evaluation Criteria for APIs","docId":"capture-interface/evaluation_criteria","unlisted":false},{"type":"link","href":"/docs/capture-interface/examples","label":"Examples","docId":"capture-interface/examples","unlisted":false},{"type":"link","href":"/docs/capture-interface/frameworks","label":"Open-source Capture Interface","docId":"capture-interface/frameworks","unlisted":false}],"href":"/docs/capture-interface/intro"},{"type":"category","label":"Testing PQC","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/pqc/testing-pqc","label":"Intro","docId":"pqc/testing-pqc","unlisted":false},{"type":"link","href":"/docs/pqc/reference-implementations","label":"Reference Implementations","docId":"pqc/reference-implementations","unlisted":false},{"type":"link","href":"/docs/pqc/datasets","label":"Datasets","docId":"pqc/datasets","unlisted":false},{"type":"link","href":"/docs/pqc/analysis-techniques","label":"Analysis Techniques","docId":"pqc/analysis-techniques","unlisted":false}],"href":"/docs/pqc/intro"},{"type":"category","label":"AI","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/ai/","label":"Intro","docId":"ai/ai","unlisted":false},{"type":"link","href":"/docs/ai/fundamentals","label":"Fundamentals of AI","docId":"ai/fundamentals","unlisted":false},{"type":"link","href":"/docs/ai/ai-for-attacks","label":"AI for Implementation Attacks","docId":"ai/ai-for-attacks","unlisted":false},{"type":"link","href":"/docs/ai/attacks-on-ai","label":"Implementation Attacks on AI","docId":"ai/attacks-on-ai","unlisted":false},{"type":"link","href":"/docs/ai/datasets","label":"Datasets","docId":"ai/datasets","unlisted":false}],"href":"/docs/ai/intro"},{"type":"link","href":"/docs/phd/intro","label":"PhD","docId":"phd/intro","unlisted":false}]},"docs":{"ai/ai":{"id":"ai/ai","title":"Intro","description":"The document takes a dual view on hardware implementation security testing and AI. First, AI techniques can improve the analysis of designs for implementation security vulnerabilities. Second, AI implementations themselves may be susceptible to implementation security vulnerabilities. Either aspect of AI and hardware security is the subject of active research with many unresolved questions. The working group aims to identify basic reference materials for new researchers, topic trees and references for existing researchers, and opportunities for open tools, interfaces and metrics to drive AI for security/ security for AI.","sidebar":"tutorialSidebar"},"ai/ai-for-attacks":{"id":"ai/ai-for-attacks","title":"AI for Implementation Attacks","description":"The working group discussed a structured representation of the domain of AI for Implementation Attacks with 7 major topics.","sidebar":"tutorialSidebar"},"ai/attacks-on-ai":{"id":"ai/attacks-on-ai","title":"Implementation Attacks on AI","description":"The working group also discussed implementation attacks on AI by starting with the attacker model. Because of the diversity of use cases and attack models, when compared to traditional cryptographic assets, the working group selected two specific attacker models for further discussion. The first attacker model applies to the embedded case, where the attacker has access to the physical implementation of the neural network. The second attacker model applies to the cloud setting, where the attacker needs to mount attacks indirectly by manipulating/observing computing resources that are physically close to the neural network implementation.","sidebar":"tutorialSidebar"},"ai/datasets":{"id":"ai/datasets","title":"Datasets","description":"The working group observes that there is no common methodology or practice to systematically share datasets in the context of AI for implementation security testing. This problem was also observed earlier during the OPTIMIST discussions on Standard File Formats for side-channel traces. ASCAD is a good starting point; ScapeGOAT offers an ability to store metadata and to organize trace sets hierarchically. For long-term storage, the working group concluded that zenodo.org, figshare.com, and huggingface.co are possible containers. Zenodo offers a DOI for the data; huggingface offers free storage as long as the data is publicly shared. The following table is a partial list of known public datasets with variable and fixed keys.","sidebar":"tutorialSidebar"},"ai/fundamentals":{"id":"ai/fundamentals","title":"Fundamentals of AI","description":"The working group collected the following pointers as a starting point for new researchers and practitioners in the field of AI for implementation security.","sidebar":"tutorialSidebar"},"ai/intro":{"id":"ai/intro","title":"Acceleration of AI for Implementation Security Testing","description":"This document reviews the state of open tools, data and methods related to the use of AI acceleration platforms and AI algorithms for implementation security testing. The document also identifies the key areas for improvements and potential for standardization. Previous OPTIMIST documents already discuss the file format for side-channel traces, the capture interface, and PQC testing methods for implementation security testing campaigns.","sidebar":"tutorialSidebar"},"capture-interface/components":{"id":"capture-interface/components","title":"Components","description":"A typical side-channel and fault analysis setup consists of multiple components. The components are:","sidebar":"tutorialSidebar"},"capture-interface/evaluation_criteria":{"id":"capture-interface/evaluation_criteria","title":"Evaluation Criteria for APIs","description":"The design and use of APIs aim to ease experiments and increase their quality. Some of the most important criteria for evaluating an API are:","sidebar":"tutorialSidebar"},"capture-interface/examples":{"id":"capture-interface/examples","title":"Examples","description":"The interfaces mentioned above have been employed in commercial and open-source setups. Here, we include the interfaces in two setups, namely FOBOS [2] and ChipWhisperer [3].","sidebar":"tutorialSidebar"},"capture-interface/frameworks":{"id":"capture-interface/frameworks","title":"Open-source Capture Interface","description":"Table 1 lists some of the open-source frameworks. As can be seen, a few frameworks offer publicly available capture interfaces. The lack of such interfaces not only affects the reproducibility of the results in SCA but also negatively impacts certification laboratories and standardization bodies that assess attack costs corresponding to side-channel and fault analysis.","sidebar":"tutorialSidebar"},"capture-interface/glossary":{"id":"capture-interface/glossary","title":"Glossary","description":"This section enumerates and defines common terms related to capturing side-channel leakage. This list encompasses (virtually) the same definitions as in the OPTIMIST\u2019s document describing \u201cFile Format for Traces\u201d [1].","sidebar":"tutorialSidebar"},"capture-interface/intro":{"id":"capture-interface/intro","title":"Capture Interface for Side Channel and Fault Injection Setups","description":"This document provides information about existing capture interfaces to suggest evaluation criteria and recommended features useful for implementation security testing.","sidebar":"tutorialSidebar"},"capture-interface/usual_interfaces":{"id":"capture-interface/usual_interfaces","title":"Usual Interfaces in Practice","description":"This section enumerates the interfaces that exist in typical side-channel and fault analysis setups.","sidebar":"tutorialSidebar"},"file-format/evaluation-criteria":{"id":"file-format/evaluation-criteria","title":"File Format Evaluation Criteria","description":"(in alphabetic order)","sidebar":"tutorialSidebar"},"file-format/existing-formats":{"id":"file-format/existing-formats","title":"Examples","description":"This section provides examples of existing file formats for traces of side-channel leakage, including pointers to source code and reference implementations.","sidebar":"tutorialSidebar"},"file-format/glossary":{"id":"file-format/glossary","title":"Glossary","description":"This section enumerates and defines common terms related to the file format for traces of side-channel leakage.","sidebar":"tutorialSidebar"},"file-format/intro":{"id":"file-format/intro","title":"File Format for Traces","description":"This document is a list of common terms and requirements relevantto a file format for measurement data from implementation security testing,with an emphasis on data that represents side-channel leakage.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Introduction","description":"Welcome to the Optimist Hour!","sidebar":"tutorialSidebar"},"phd/intro":{"id":"phd/intro","title":"OPTIMIST PhD Forum","description":"The OPTIMIST PhD Forum is oriented at Ph.D. students working on topics related to AI and side-channel analysis (SCA). The goal is to create an interactive environment where students:","sidebar":"tutorialSidebar"},"pqc/analysis-techniques":{"id":"pqc/analysis-techniques","title":"Analysis Techniques","description":"We identify several challenges in extending common testing methods for post-quantum cryptography.  TVLA as such has been used extensively in both academic work as well as in the industry evaluation of side-channels.  However, the TVLA application for post-quantum sub-routines is non-trivial and may generate incorrect results.  Open source analysis techniques and establishing best practices are critical as PQC deployments are emerging.","sidebar":"tutorialSidebar"},"pqc/datasets":{"id":"pqc/datasets","title":"Datasets","description":"We identify a critical gap in open-source datasets for the implementation security testing of post-quantum cryptography.  The following are our guidelines for generating this dataset for side-channel analysis.  Fault injection datasets would also be useful, but need more research maturity before discussing specifics.","sidebar":"tutorialSidebar"},"pqc/intro":{"id":"pqc/intro","title":"Testing Post-Quantum Cryptography Implementation Security","description":"This document consolidates community-driven insights and recommendations for implementation security testing of post-quantum cryptography, detailing essential terminology, open-source tools, hardware/software implementations, and strategies for creating reproducible side-channel datasets tailored to the unique challenges of PQC algorithms.","sidebar":"tutorialSidebar"},"pqc/reference-implementations":{"id":"pqc/reference-implementations","title":"Reference Implementations","description":"Software Implementations","sidebar":"tutorialSidebar"},"pqc/testing-pqc":{"id":"pqc/testing-pqc","title":"Intro","description":"Post-Quantum Cryptography (PQC) has become one of the most critical fields due to the anticipated emergence of quantum computers that could be capable of rendering widely deployed public-key cryptographic algorithms ineffective. RSA, DSA, and ECC are among such algorithms. As emphasized in the recent PQC roadmap published by MITRE Corporation [1], this presents an urgent security challenge, particularly in the context of adversaries who may already be collecting and storing encrypted data with the intent to decrypt it once sufficient quantum capabilities become available. To mitigate these long-term risks, it is imperative that organizations begin transitioning to quantum-resistant algorithms now.","sidebar":"tutorialSidebar"}}}}')}}]);